import{z as o,x as i,o as A,c as F,q as B,j as r,D as a,d as e,s,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"FSQ / LFQ","description":"","frontmatter":{"title":"FSQ / LFQ","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fsq-lfq.md","filePath":"llm/fsq-lfq.md","lastUpdated":1791413859000}'),d={name:"llm/fsq-lfq.md"};function D(p,E,m,Q,f,h){const l=i("Mermaid");return A(),F("div",null,[E[2]||(E[2]=B('<h1 id="fsq-lfq" tabindex="-1">FSQ / LFQ <a class="header-anchor" href="#fsq-lfq" aria-label="Permalink to &quot;FSQ / LFQ&quot;">​</a></h1><div class="epigraph"><p>码本学习会崩溃。把每个维直接量化到固定网格，或对符号做无查找量化，词表变成设计出来的，而不是抢着用的。</p><footer>—— Mentzer 等 FSQ；Yu 等 MAGVIT-v2 的 Lookup-Free Quantization</footer></div><p><a href="/llm/vqgan">上一课</a>仍要维护可学习码本。Mentzer 等人的有限标量量化（FSQ）对每个通道独立量化到少量水平；Yu 等人的 LFQ 用符号位组合出词表，前向无码本查找。缺口是量化器的稳定性。后课连续对离散默认：离散侧不一定再背一个大码本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VQ 的最近邻与 EMA 码本在大数据上仍会死码、要调承诺损失。FSQ：令 \\(z\\in\\mathbb{R}^{d}\\)，每维量化到 \\(L\\) 档，词表大小 \\(L^{d}\\)（\\(d\\) 很小）。没有可学习 \\(e_k\\)，崩溃被结构禁止。LFQ：对二元或低比特维做查找无关的整数编码，同样避免码本抢占。二者用重构 + 辅助损失训练编码器/解码器。</p><p><span class="marginnote">「码本崩溃」可以想象成食堂窗口：训练早期几个热门码字抢走几乎所有客流，其余窗口永远没人排队（死码），最后词表名义上有一万个码字、实际只在用几十个。FSQ 的做法等价于把窗口固定死、谁也别想扩张，食物（编码器输出）只能自己往窗口送。</span></p><p><span class="marginnote">数字实例：FSQ 论文常用 \\(L=5\\)、\\(d=6\\)，词表就是 \\(5^6 = 15625\\) 个格点——和常见 VQ 词表同一量级，却不带任何可学习码字。想扩词表？加一维就是 \\(5^7=78125\\)；但每加一维，编码器要把更多信息塞进这一维的 5 个档位，重构难度也随之上升。</span></p><p>权衡：网格量化在感知上可能弱于精心学的码本，要靠解码器与损失补；词表大小由网格组合爆炸，维数必须小。</p><p><span class="marginnote">FSQ 的「词表」是笛卡尔网格，LM 看到的 ID 是网格坐标的编码。ID 的邻域结构与语义邻域不必一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(L\\) 与通道数使词表与序列长度可接 LM。训练盯重构与有效使用率（网格点是否都被访问）。接自回归时，ID 映射必须冻结，否则旧检查点的 token 失效。与 VQGAN 比，GAN 仍可加在解码器上，量化器本身更简单。</p>',11)),(A(),r(n,null,{default:a(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ZE%5B%22%E8%BF%9E%E7%BB%AD%20z%22%5D%20--%3E%20FSQ%5B%22%E9%80%90%E7%BB%B4%E7%BD%91%E6%A0%BC%E9%87%8F%E5%8C%96%22%5D%0A%20%20ZE%20--%3E%20LFQ%5B%22%E6%97%A0%E6%9F%A5%E6%89%BE%E6%AF%94%E7%89%B9%E9%87%8F%E5%8C%96%22%5D%0A%20%20FSQ%20--%3E%20ID%5B%22%E5%9B%BA%E5%AE%9A%E8%AF%8D%E8%A1%A8%20ID%22%5D%0A%20%20LFQ%20--%3E%20ID%0A%20%20ID%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"可学习码本是聚类：热门模式抢走码字。固定网格把容量均匀铺在坐标箱上，编码器必须把语义放进这些箱的组合。这更稳，但把几何负担全交给编码器。LM 建模的是箱下标的语法，不是码向量的余弦。",-1)),(A(),r(n,null,{default:a(()=>[s(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20VQ%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E7%A0%81%E6%9C%AC%EF%BC%88VQ%EF%BC%89%22%5D%0A%20%20%20%20E1%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E8%BE%93%E5%87%BA%E5%90%91%E9%87%8F%22%5D%20--%3E%20N1%5B%22%E6%89%BE%E6%9C%80%E8%BF%91%E7%A0%81%E5%AD%97%22%5D%0A%20%20%20%20N1%20--%3E%20U1%5B%22%E7%A0%81%E5%AD%97%E9%9A%8F%E6%A2%AF%E5%BA%A6%2FEMA%20%E6%8C%AA%E5%8A%A8%22%5D%0A%20%20%20%20U1%20--%3E%20R1%7B%22%E7%83%AD%E9%97%A8%E7%A0%81%E5%AD%97%E8%B6%8A%E6%8A%A2%E8%B6%8A%E5%A4%9A%EF%BC%9F%22%7D%0A%20%20%20%20R1%20--%20%22%E6%98%AF%22%20--%3E%20D1%5B%22%E6%AD%BB%E7%A0%81%20%2B%20%E9%9C%80%E8%A6%81%E9%87%8D%E5%90%AF%2F%E6%89%BF%E8%AF%BA%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20end%0A%20%20subgraph%20FG%5B%22%E5%9B%BA%E5%AE%9A%E7%BD%91%E6%A0%BC%EF%BC%88FSQ%2FLFQ%EF%BC%89%22%5D%0A%20%20%20%20E2%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E8%BE%93%E5%87%BA%E5%90%91%E9%87%8F%22%5D%20--%3E%20Q2%5B%22%E9%80%90%E7%BB%B4%E5%9B%9B%E8%88%8D%E4%BA%94%E5%85%A5%E5%88%B0%E5%9B%BA%E5%AE%9A%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20%20%20Q2%20--%3E%20U2%5B%22%E7%BD%91%E6%A0%BC%E6%B0%B8%E4%B8%8D%E6%8C%AA%E5%8A%A8%22%5D%0A%20%20%20%20U2%20--%3E%20D2%5B%22%E6%97%A0%E6%AD%BB%E7%A0%81%E9%97%AE%E9%A2%98%EF%BC%8C%E5%87%A0%E4%BD%95%E8%B4%9F%E6%8B%85%E5%85%A8%E5%9C%A8%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">「承诺损失」（commitment loss）是 VQ 时代的小拐杖：一项惩罚，逼着编码器输出「承诺」待在选中的码字附近，别每步都跳来跳去。调它是个手艺活。FSQ 直接四舍五入、梯度用直通估计回传，这项拐杖整个不需要了——这也是它「稳」的来源之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有生成系统都要离散。下一课把连续潜变量（扩散/流）与离散 token 两条路对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FSQ / LFQ 用固定网格或无查找编码避免码本崩溃。</li><li>词表是设计量；ID 邻域不等于语义邻域。</li><li>稳定性换来的负担在编码器与解码器。</li><li>出处：Mentzer 等 FSQ；Yu 等 MAGVIT-v2 / LFQ。</li></ul>',5))])}const _=o(d,[["render",D]]);export{C as __pageData,_ as default};
